from __future__ import annotations
import argparse,json,math
from pathlib import Path
from typing import Any
import numpy as np
from .plant import AnalyticJudge,FossenParameters,PlantState,wrap

def validate_trace(arm:str,trace:dict[str,Any],*,position_tight_m:float=.031,heading_tight_rad:float=.028,flag_multiplier:float=3.)->dict[str,Any]:
 samples=trace["samples"];actions=trace["action_trace"];initial=samples[0]["state"] if samples else trace["reset"]["initial_state"];judge=AnalyticJudge(FossenParameters(),dt_s=float(trace.get("sample_interval_s",.05)));judge.reset(PlantState(*map(float,initial[:6])));position_errors=[];heading_errors=[]
 for index,sample in enumerate(samples[1:],start=1):
  action_row=actions[min((index-1)//2,len(actions)-1)];command=action_row.get("command",action_row);state=judge.step(command[:2]);native=sample["state"];position_errors.append(math.hypot(state.north_m-native[0],state.east_m-native[1]));heading_errors.append(abs(wrap(state.heading_rad-native[2])))
 position_rmse=float(np.sqrt(np.mean(np.square(position_errors))));heading_rmse=float(np.sqrt(np.mean(np.square(heading_errors))));gap=float(math.hypot(position_rmse/position_tight_m,heading_rmse/heading_tight_rad));clean=position_rmse<=position_tight_m and heading_rmse<=heading_tight_rad;flagged=position_rmse<=flag_multiplier*position_tight_m and heading_rmse<=flag_multiplier*heading_tight_rad;vehicle_c=trace.get("vehicle_id") in ("vehicle-c","vehicle-c-azimuth");known=trace.get("known_vehicle_c_residual",{});consistent=vehicle_c and position_rmse<=float(known.get("position_rmse_m_max",-1)) and heading_rmse<=float(known.get("heading_rmse_rad_max",-1));classification="clean" if clean else "flagged" if flagged else "vehicle-c-known-residual" if consistent else "failed";return {"arm":arm,"vehicle_id":trace.get("vehicle_id"),"position_rmse_m":position_rmse,"heading_rmse_rad":heading_rmse,"domain_gap":gap,"tight_band":{"position_m":position_tight_m,"heading_rad":heading_tight_rad},"flag_multiplier":flag_multiplier,"classification":classification,"passed_numeric":classification!="failed","position_excess_over_tight_m":position_rmse-position_tight_m,"heading_excess_over_tight_rad":heading_rmse-heading_tight_rad,"meaning":"normalized open-loop trajectory RMSE; determinism is tested separately"}
def main():
 p=argparse.ArgumentParser();p.add_argument("--traces",type=Path,required=True,help="JSON mapping each arm to a same-plant native trace path");p.add_argument("--output",type=Path,required=True);p.add_argument("--human-reviewed",action="store_true",help="Record that a human reviewed all numeric classifications");a=p.parse_args();paths=json.loads(a.traces.read_text());rows=[validate_trace(arm,json.loads(Path(path).read_text())) for arm,path in sorted(paths.items())];required={"bcod-sim","gazebo","holoocean","stonefish"};numeric_pass={r["arm"] for r in rows}==required and all(r["passed_numeric"] for r in rows);passed=numeric_pass and a.human_reviewed;report={"schema_version":1,"artifact_kind":"analytic-judge-domain-gap-validation","passed":passed,"numeric_passed":numeric_pass,"human_reviewed":a.human_reviewed,"arms":rows,"claim_scope":"judge is independent of training arms but is not asserted dynamics-neutral","known_limitation":"Vehicle C retains an unresolved lateral/heading drift under symmetric thrust; the analytic judge is the best currently validated model, not ground truth."};a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(report,indent=2)+"\n");print(json.dumps(report,indent=2));raise SystemExit(0 if passed else 2)
if __name__=="__main__":main()
